void RegisterGeneratedNatives()
{
    g_pSource2ModNatives->AddNatives(g_natives);
}

void ForgetGeneratedCalls(PluginId id)
{
    std::erase_if(g_pending, [id](const auto& c) { return c->owner == id; });
}

void ClearGeneratedCalls()
{
    g_pending.clear();
}
